Lemma rw_cells_reshape : forall m A cs1 cs2,
  cells_bytes cs1 = cells_bytes cs2 -> cells_size cs1 = cells_size cs2 -> cells_wf cs2 -> rw_cells bsegs m A cs1 -> rw_cells bsegs m A cs2.
Proof. intros m A cs1 cs2 EB ES WF [[W1 B1] WR]. split; [split; [exact WF| rewrite <- EB; exact B1]| rewrite <- ES; exact WR]. Qed.

(* [comment removed for export] *)
Definition ia_after (m : mem) : Prop :=
     u8arr bsegs m AIAINST (repeat (b8 0) (Z.to_nat 0x40dc0))
  /\ rw_cells bsegs m (AIAINST + 0x40dc0) [C8 (wz 4096); C8 (wz (AIAINST + 0x40dd0))]
  /\ u8arr bsegs m (AIAINST + 0x40dd0) (repeat (b8 0) (Z.to_nat (0x81030 - 0x40dd0))).
Definition ia_pristine (m : mem) : Prop := u8arr bsegs m AIAINST (repeat (b8 0) (Z.to_nat 0x81030)).

Definition ia_post (ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo : Z) : machine_state -> Prop :=
  fun ms' => exists (a1 a2 a3 a4 a5 a6 : word) m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz AIAINST) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 48, bv_unsigned sp); (AIAINIT, AIAINIT + 4); (AIAINST, AIAINST + 0x81030)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' AIAINIT [C1 (b8 1); C1 (b8 0); C2 (wz 0)]
    /\ ia_after m'.

